// FUNCTIONS //

/**
* Builds a single tick data record comparing exact and rendered positions.
*
* @private
* @param {number} idx - tick index
* @param {number} labelX - exact unrounded pixel coordinate
* @param {number} tickX - rendered tick pixel coordinate
* @returns {Object} tick record
*/
function buildTickRoundRow( idx, labelX, tickX ) {
	var shifted;
	var stemEnd;
	var headX;
	var pillW;
	var tag;
	var lx;
	var rx;

	lx = round( labelX * 10 ) / 10;
	rx = round( tickX * 10 ) / 10;
	shifted = abs( rx - lx ) > 1e-6;
	if ( shifted ) {
		tag = lx + ' \u2192 ' + rx;
		pillW = 52;
		if ( rx < lx ) {
			stemEnd = rx + 0.08;
			headX = rx + 0.07;
		} else {
			stemEnd = rx - 0.08;
			headX = rx - 0.07;
		}
	} else {
		tag = rx + 'px';
		pillW = 38;
		stemEnd = rx;
		headX = rx;
	}
	return {
		'label': String( idx ),
		'exactX': lx,
		'tickX': rx,
		'shifted': shifted,
		'midX': ( lx + rx ) / 2,
		'tag': tag,
		'pillWidth': pillW,
		'stemEndX': stemEnd,
		'headX': headX
	};
}

/**
* Creates a pixel-grid Vega specification for visualizing `tickRound`.
*
* @private
* @param {boolean} tickRound - boolean indicating whether tick positions are rounded
* @returns {Object} Vega specification
*/
function createTickRoundSpec( tickRound ) {
	var interiorRows;
	var shiftedRight;
	var shiftedLeft;
	var shiftedRows;
	var labelX;
	var tickX;
	var rows;
	var row;
	var i;

	rows = [];
	interiorRows = [];
	shiftedLeft = [];
	shiftedRight = [];
	for ( i = 0; i <= 5; i += 1 ) {
		labelX = round( ( i * 2.4 ) * 10 ) / 10;
		if ( tickRound ) {
			tickX = round( labelX );
		} else {
			tickX = labelX;
		}
		row = buildTickRoundRow( i, labelX, tickX );
		rows.push( row );
		if ( i > 0 && i < 5 ) {
			interiorRows.push( row );
		}
		if ( row.shifted && row.tickX < row.exactX ) {
			shiftedLeft.push( row );
		} else if ( row.shifted && row.tickX > row.exactX ) {
			shiftedRight.push( row );
		}
	}
	shiftedRows = shiftedLeft.concat( shiftedRight );

	return {
		'$schema': SCHEMA,
		'width': BASE_WIDTH,
		'height': 76,
		'padding': BASE_PADDING,
		'background': '#ffffff',
		'data': [
			{
				'name': 'ticks',
				'values': rows
			},
			{
				'name': 'interior',
				'values': interiorRows
			},
			{
				'name': 'shifted',
				'values': shiftedRows
			},
			{
				'name': 'shiftedLeft',
				'values': shiftedLeft
			},
			{
				'name': 'shiftedRight',
				'values': shiftedRight
			}
		],
		'scales': TICK_ROUND_SCALES,
		'axes': TICK_ROUND_AXES,
		'marks': TICK_ROUND_MARKS
	};
}

/**
* Creates a Vega specification from a figure configuration.
*
* @private
* @param {Object} config - figure configuration
* @param {Object} config.axis - Vega axis object
* @param {number} [config.width] - override width
* @param {number} [config.height] - override height
* @param {(number|Object)} [config.padding] - override padding
* @param {string} [config.background] - background color
* @param {Object} [config.encode] - Vega frame encode definitions
* @param {Array} [config.data] - Vega data definitions
* @param {Array} [config.scales] - Vega scale definitions
* @param {Array} [config.marks] - Vega mark definitions
* @returns {Object} Vega specification
*/
function createSpec( config ) {
	var spec;
	var axis;

	if ( config.type === 'tickRound' ) {
		return createTickRoundSpec( config.axis.tickRound );
	}
	axis = config.axis;
	if ( axis.domainColor === void 0 ) {
		axis.domainColor = '#000000';
	}
	if ( axis.title !== void 0 && axis.titlePadding === void 0 ) {
		axis.titlePadding = 10;
	}
	if ( axis.zindex === void 0 ) {
		axis.zindex = 1;
	}
	spec = {
		'$schema': SCHEMA,
		'width': config.width || BASE_WIDTH,
		'height': config.height || BASE_HEIGHT,
		'padding': config.padding || BASE_PADDING,
		'background': config.background || '#ffffff',
		'data': config.data || [],
		'scales': config.scales || DEFAULT_SCALES,
		'axes': [ axis ],
		'marks': config.marks || GROUP_RECT_MARKS,
		'encode': config.encode || {}
	};
	return spec;
}

/**
* Generates all figure SVGs sequentially.
*
* @private
* @param {Array} figures - figure configuration array
* @param {Callback} clbk - callback to invoke upon completion
* @returns {void}
*/
function generateAll( figures, clbk ) {
	var idx = 0;
	next();

	/**
	* Processes the next figure in the queue.
	*
	* @private
	* @returns {void}
	*/
	function next() {
		var outputPath;
		var config;
		var spec;

		if ( idx >= figures.length ) {
			return clbk( null );
		}
		config = figures[ idx ];
		spec = createSpec( config );
		outputPath = join( IMG_DIR, config.name + '.svg' );

		debug( 'Rendering: %s', config.name );
		renderFig( outputPath, spec, onDone );
	}

	/**
	* Callback invoked upon completing a figure render.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @returns {void}
	*/
	function onDone( error ) {
		if ( error ) {
			return clbk( error );
		}
		debug( '  -> %s', join( IMG_DIR, figures[ idx ].name + '.svg' ) );
		idx += 1;
		next();
	}
}

/**
* Removes stale SVG files from a directory listing.
*
* @private
* @param {Array} files - directory entries
* @throws {Error} if unable to remove a stale file
* @returns {void}
*/
function removeStaleFiles( files ) {
	var valid;
	var file;
	var err;
	var f;
	var i;
	var j;

	for ( i = 0; i < files.length; i++ ) {
		file = files[ i ];
		if ( extname( file ) !== '.svg' ) {
			continue;
		}
		valid = false;
		for ( j = 0; j < FIGURES.length; j++ ) {
			f = FIGURES[ j ].name + '.svg';
			if ( file === f ) {
				valid = true;
				break;
			}
		}
		if ( !valid ) {
			debug( 'Removing stale SVG: %s', file );
			err = unlinkSync( join( IMG_DIR, file ) );
			if ( err instanceof Error ) {
				throw err;
			}
		}
	}
}


// MAIN //

/**
* Generates all axis documentation figures.
*
* @private
* @returns {void}
*/
function main() {
	var files;

	if ( existsSync( IMG_DIR ) ) {
		files = readdirSync( IMG_DIR );
		if ( files instanceof Error ) {
			console.error( 'Error reading directory: %s', files.message ); // eslint-disable-line no-console
			process.exitCode = 1;
			return;
		}
		removeStaleFiles( files );
	}
	// Generate all figure SVGs:
	generateAll( FIGURES, onComplete );

	/**
	* Callback invoked upon completing all figure generation.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @returns {void}
	*/
	function onComplete( error ) {
		if ( error ) {
			console.error( 'Error generating figures: %s', error.message ); // eslint-disable-line no-console
			process.exitCode = 1;
			return;
		}
		console.log( 'Successfully generated %d axis figures.', FIGURES.length ); // eslint-disable-line no-console
	}
}

main();
